head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "options.useModalStack(선택) 파라미터를 true 로 설정하면, options.modal 속성이 true 일때 여러 개의 팝업을 생성할 경우 마지막 팝업만 활성화되고 다른 팝업은 컨트롤 할 수 없습니다.",
        "options.useModalStack(선택) 파라미터를 false 로 설정하면, options.modal 속성이 true 일때 여러 개의 팝업을 생성할 경우 모든 팝업을 컨트롤 할 수 있습니다.",
        "options.useModalStack(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
        "options.useModalDisable(선택) 파라미터를 true 로 설정하면, options.modal 속성이 true 이고 options.useModalStack 속성이 false 일때 팝업을 호출한 부모 창의 컴포넌트를 비활성화(disabled) 처리합니다.",
        "options.useModalDisable(선택) 파라미터를 true 로 설정하면, Tab 키 등을 사용하여 부모 창의 컴포넌트로 접근하는 것도 차단합니다.",
        "options.useModalDisable(선택) 파라미터를 false 로 설정하면, 팝업을 호출한 부모 창의 컴포넌트를 비활성화(disabled) 처리하지 않습니다.",
        "options.useModalDisable(선택) 파라미터 생략 시, 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    $c.gcm.createLabel('label="[전제] openPopup 클릭 시 wframePopup 2개(popup_1, popup_2)를 차례로 엽니다.\n[확인] 각 팝업 머리글을 클릭해 조작 가능 여부를 확인하고, popup_2 입력창에서 Tab 키를 반복해 부모 화면 컴포넌트로 포커스가 이동하는지 확인합니다(이동하면 처음 포커스를 받은 부모 화면 컴포넌트를 출력합니다)."', '', 'label1');

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    document.addEventListener("focusin", scwin.onParentFocusin, true);
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback, delay) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) setTimeout(callback, delay || 1500);
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



// options.id 로 팝업 정보 조회 (Page Scope 적용 시 실행 ID 는 'mf_' 접두사가 붙음)
scwin.findPopup = function (id) {
    let list = $p.getAllPopupList();
    for (let i = list.length - 1; i >= 0; i--) {
        if ((list[i].options.org_id === id || list[i].options.id === id) && list[i].popupWin) return list[i];
    }
    return null;
};



// options.id 로 팝업 최상위 div 조회
scwin.popupEl = function (id) {
    return document.querySelector(".w2popup_window[id$='" + id + "']");
};



// 팝업 내부 요소(타이틀바 버튼 등) 조회
scwin.popupPart = function (id, suffix) {
    let el = scwin.popupEl(id);
    return el ? document.getElementById(el.id + "_" + suffix) : null;
};



scwin.rectStr = function (el) {
    let r = el.getBoundingClientRect();
    return "left " + Math.round(r.left + window.scrollX) + ", top " + Math.round(r.top + window.scrollY) + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height);
};

scwin.btn_openPopup_onclick = function () {
    let modal = par_modal.getValue();
    let useModalStack = par_useModalStack.getValue();
    let useModalDisable = par_useModalDisable.getValue();

    let optionList = [];
    let pos = [["popup_1", "100px", "100px"], ["popup_2", "380px", "200px"]];
    for (let i = 0; i < pos.length; i++) {
        let options = { id: pos[i][0], type: "wframePopup", left: pos[i][1], top: pos[i][2], width: "420px", height: "300px", popupName: pos[i][0], modal: (modal === "true") };
        if (useModalStack !== "") options.useModalStack = (useModalStack === "true");
        if (useModalDisable !== "") options.useModalDisable = (useModalDisable === "true");
        optionList.push(options);
    }

    scwin.watchParentFocus = false;
    scwin.runOpenPopup(optionList, scwin.printResult);
};



// 팝업 머리글 위치에서 실제 클릭 대상이 그 팝업인지 판정
scwin.isClickable = function (id) {
    let el = scwin.popupEl(id);
    let header = scwin.popupPart(id, "header");
    if (!el || !header) return false;
    let r = header.getBoundingClientRect();
    let hit = document.elementFromPoint(r.left + 15, r.top + r.height / 2);
    return !!hit && el.contains(hit);
};



// validation 1~7 판정 출력 (팝업 조작 가능 여부 / 부모 창 컴포넌트 disabled)
scwin.printResult = function () {
    scwin.out("popup_1 조작 가능 : " + scwin.isClickable("popup_1") + " / popup_2 조작 가능 : " + scwin.isClickable("popup_2")
        + " / 부모 창 openPopup 버튼 disabled : " + btn_openPopup.getDisabled());
    scwin.watchParentFocus = true;
};



// validation 5, 6 판정 출력 : 팝업이 열린 동안 Tab 등으로 부모 화면 컴포넌트가 포커스를 받으면 처음 1회 출력
scwin.watchParentFocus = false;
scwin.onParentFocusin = function (e) {
    if (!scwin.watchParentFocus || $p.getAllPopupList().length === 0) return;
    let ctrls = [par_modal, par_useModalStack, par_useModalDisable, btn_openPopup];
    for (let i = 0; i < ctrls.length; i++) {
        let el = document.getElementById(ctrls[i].id);
        if (el && el.contains(e.target)) {
            scwin.watchParentFocus = false;
            scwin.out("부모 창 컴포넌트 포커스 이동 : " + ctrls[i].getOriginalID());
            return;
        }
    }
};
